CREATE INDEX "memberships_renewal_window_idx" ON "memberships" USING btree ("billing_period_end","id") WHERE "memberships"."billing_period_end" IS NOT NULL AND "memberships"."status" IN ('active','past_due') AND "memberships"."cancel_at_period_end"=false AND "memberships"."billing_interval"<>'none' AND "memberships"."grant_effective_at" IS NULL AND "memberships"."grant_expires_at" IS NULL;